import{_ as t,o,c as a,a2 as d}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"How do I delete devices and clean up old datapoints?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/02.anleitungen/02.geraete-verwalten.md"},"headers":[],"relativePath":"adapter/esphome/anleitungen/geraete-verwalten.md","filePath":"adapter/esphome/anleitungen/geraete-verwalten.md","lastUpdated":null}'),n={name:"adapter/esphome/anleitungen/geraete-verwalten.md"};function s(i,e,r,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="how-do-i-delete-devices-and-clean-up-old-datapoints" tabindex="-1">How do I delete devices and clean up old datapoints? <a class="header-anchor" href="#how-do-i-delete-devices-and-clean-up-old-datapoints" aria-label="Permalink to &quot;How do I delete devices and clean up old datapoints?&quot;">​</a></h1><p><a id="delete-device-completely-objects-come"></a></p><h2 id="how-do-i-delete-a-device-completely-and-why-do-the-objects-come-back" tabindex="-1">How do I delete a device completely and why do the objects come back? <a class="header-anchor" href="#how-do-i-delete-a-device-completely-and-why-do-the-objects-come-back" aria-label="Permalink to &quot;How do I delete a device completely and why do the objects come back?&quot;">​</a></h2><p>Always delete a device in the tab &quot;Devices&quot;: choose &quot;Delete device&quot; on the device and confirm. The adapter then disconnects and deletes the device with all its states. This cannot be undone.</p><p>If you only delete the objects in the tab &quot;Objects&quot; instead, the device stays connected in the running adapter. It creates the objects again on the next connection.</p><p>If the device keeps running after deletion, discovery finds it again. It then shows up under &quot;Discovered, not added yet&quot;, without states. To keep it from appearing there, switch it off or add its address to the exclusion list of discovery.</p><p><strong>See also:</strong> <a href="./geraete-entdecken#auto-discovery-report-routers-foreign">Exclude an address from discovery</a> · <a href="#clean-up-devices-datapoints-no">Clean up old devices</a></p><p><a id="clean-up-devices-datapoints-no"></a></p><h2 id="how-do-i-clean-up-devices-and-datapoints-that-no-longer-exist" tabindex="-1">How do I clean up devices and datapoints that no longer exist? <a class="header-anchor" href="#how-do-i-clean-up-devices-and-datapoints-that-no-longer-exist" aria-label="Permalink to &quot;How do I clean up devices and datapoints that no longer exist?&quot;">​</a></h2><p>The adapter cleans up in two ways.</p><p><strong>Automatically:</strong> 10 seconds after a device connects, the adapter deletes all folders under that device that the device no longer reports, e.g. after you removed an entity from the YAML. Single states in folders that are still reported stay. Delete them in the tab &quot;Objects&quot; if needed.</p><p><strong>By hand:</strong> The state <code>esphome.0.info.deviceCleanup</code> deletes all devices whose <code>info._online</code> is currently <code>false</code>, with all their states. Set it to <code>true</code> in the tab &quot;Objects&quot;.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><code>info.deviceCleanup</code> does not ask. It also deletes devices that are only offline for a moment, with their states and stored credentials.</p></div><p>If a device deleted this way comes back online while the instance runs, the adapter creates it again. To get rid of a single device for good, delete it in the tab &quot;Devices&quot;.</p><p><strong>See also:</strong> <a href="#delete-device-completely-objects-come">Delete a device completely</a></p><p><a id="recover-stored-masked-api-password"></a></p><h2 id="how-do-i-recover-the-stored-masked-api-password-or-key" tabindex="-1">How do I recover the stored (masked) API password or key? <a class="header-anchor" href="#how-do-i-recover-the-stored-masked-api-password-or-key" aria-label="Permalink to &quot;How do I recover the stored (masked) API password or key?&quot;">​</a></h2><p>The adapter stores the key and the API password encrypted in the device object and does not show them again. That is why the fields in the dialog &quot;Change connection settings&quot; are empty. If you leave both empty, the adapter keeps the stored values.</p><p>You find the key in the device YAML under <code>api:</code> → <code>encryption:</code> → <code>key:</code>, or in <code>secrets.yaml</code> if the YAML includes it with <code>!secret</code>. Open both files in the dashboard or in the tab &quot;YAML Files&quot; with &quot;Open in Editor&quot;. The adapter does not store an OTA password.</p><p><strong>See also:</strong> <a href="./yaml-dateien#upload-view-delete-yaml-files">View YAML files</a></p>',20)])])}const v=t(n,[["render",s]]);export{u as __pageData,v as default};
